  for (const project of projects.filter(item => Boolean(item.archived) === (app.querySelector('#project-filter').value === 'Archived'))) {
    const row = document.createElement('div'); row.className = 'project-row'; row.dataset.testid = 'project-row';
    const name = document.createElement('span'); name.textContent = project.name;
    const summary = document.createElement('span'); summary.dataset.testid = 'project-summary'; summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const open = document.createElement('button'); open.type = 'button'; open.textContent = 'Open project';
